import{_ as B,H as e,f as t,i as s}from"./chunks/framework.BH2BK_3i.js";const g=JSON.parse('{"title":"第十一封信-阳光之下没什么新鲜事儿（下）","description":"","frontmatter":{},"headers":[],"relativePath":"去无方向的信/第十一封信-阳光之下没什么新鲜事儿（下）.md","filePath":"去无方向的信/第十一封信-阳光之下没什么新鲜事儿（下）.md","lastUpdated":1795542896000}'),i={name:"去无方向的信/第十一封信-阳光之下没什么新鲜事儿（下）.md"};function a(n,E,A,p,o,r){return e(),t("div",null,[...E[0]||(E[0]=[s('<h1 id="第十一封信-阳光之下没什么新鲜事儿-下" tabindex="-1">第十一封信-阳光之下没什么新鲜事儿（下） <a class="header-anchor" href="#第十一封信-阳光之下没什么新鲜事儿-下" aria-label="Permalink to &quot;第十一封信-阳光之下没什么新鲜事儿（下）&quot;">​</a></h1><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E5%258D%2581%25E4%25B8%2580%25E5%25B0%2581%25E4%25BF%25A1-%25E9%2598%25B3%25E5%2585%2589%25E4%25B9%258B%25E4%25B8%258B%25E6%25B2%25A1%25E4%25BB%2580%25E4%25B9%2588%25E6%2596%25B0%25E9%25B2%259C%25E4%25BA%258B%25E5%2584%25BF%25EF%25BC%2588%25E4%25B8%258B%25EF%25BC%2589/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E5%258D%2581%25E4%25B8%2580%25E5%25B0%2581%25E4%25BF%25A1-%25E9%2598%25B3%25E5%2585%2589%25E4%25B9%258B%25E4%25B8%258B%25E6%25B2%25A1%25E4%25BB%2580%25E4%25B9%2588%25E6%2596%25B0%25E9%25B2%259C%25E4%25BA%258B%25E5%2584%25BF%25EF%25BC%2588%25E4%25B8%258B%25EF%25BC%2589/1.png" alt=""></a></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E5%258D%2581%25E4%25B8%2580%25E5%25B0%2581%25E4%25BF%25A1-%25E9%2598%25B3%25E5%2585%2589%25E4%25B9%258B%25E4%25B8%258B%25E6%25B2%25A1%25E4%25BB%2580%25E4%25B9%2588%25E6%2596%25B0%25E9%25B2%259C%25E4%25BA%258B%25E5%2584%25BF%25EF%25BC%2588%25E4%25B8%258B%25EF%25BC%2589/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E5%258D%2581%25E4%25B8%2580%25E5%25B0%2581%25E4%25BF%25A1-%25E9%2598%25B3%25E5%2585%2589%25E4%25B9%258B%25E4%25B8%258B%25E6%25B2%25A1%25E4%25BB%2580%25E4%25B9%2588%25E6%2596%25B0%25E9%25B2%259C%25E4%25BA%258B%25E5%2584%25BF%25EF%25BC%2588%25E4%25B8%258B%25EF%25BC%2589/2.png" alt=""></a></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E5%258D%2581%25E4%25B8%2580%25E5%25B0%2581%25E4%25BF%25A1-%25E9%2598%25B3%25E5%2585%2589%25E4%25B9%258B%25E4%25B8%258B%25E6%25B2%25A1%25E4%25BB%2580%25E4%25B9%2588%25E6%2596%25B0%25E9%25B2%259C%25E4%25BA%258B%25E5%2584%25BF%25EF%25BC%2588%25E4%25B8%258B%25EF%25BC%2589/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E5%258D%2581%25E4%25B8%2580%25E5%25B0%2581%25E4%25BF%25A1-%25E9%2598%25B3%25E5%2585%2589%25E4%25B9%258B%25E4%25B8%258B%25E6%25B2%25A1%25E4%25BB%2580%25E4%25B9%2588%25E6%2596%25B0%25E9%25B2%259C%25E4%25BA%258B%25E5%2584%25BF%25EF%25BC%2588%25E4%25B8%258B%25EF%25BC%2589/3.png" alt=""></a></p><p>生生：</p><p>你好哇。</p><p>不知道你有没有出门试过“阳光十六法则”，反正试过的人都觉得这玩意儿还挺好使的。</p><p>我前段时间带一些爷爷奶奶叔叔阿姨去做拍摄练习，我提了一些看起来很严苛的要求：光圈固定在 F11，ISO 固定在 ISO400，只有快门可以调整，但快门也只能在 1/15s、1/30s、1/60s、1/125s、1/250s 和 1/500s 中选择。</p><p>我相信现在的你一定明白这些要求非但不严苛，反而是非常贴心的，因为实在是太省事。</p><p>那天多云，间有晴天，大多数场景都可以用 1/500s F11 ISO400 这组参数搞定，但我们拍摄的场地里建筑物比较多，错综复杂，所以小廊桥附近，大家可以用 1/250s；建筑阴影中，大家可以用 1/125s；密密的树荫下，大家可以用 1/60s；暗暗的连接通道里，大家可以用 1/30s或 1/15s。</p><p>除了曝光参数固定之外，白平衡、镜头焦段和对焦距离也都是固定的，这个咱们后面马上会讲到。</p><p>总而言之，当一切都固定下来以后，带来的非但不是限制，反而是自由，因为大家再也不用把本应该用在拍照片儿上的时间和精力，花在跟那儿低着头拧来拧去地“玩儿相机”上了。</p><p>按理说，有关“阳光十六法则”的东西我们基本上都讲完了，但好像还不够，因为一天中有太阳的时间毕竟不是 24 小时，或者即便一天 24 小时都有太阳，我们也不会 24 小时都待在户外，所以总还是有很多阳光覆盖不到的时刻和角落。</p><p>怎么办？</p><p>“阳光十六法则”告诉我们在阳光下应该怎么设置曝光参数，但他还有一个更重要的启示，那就是：任何环境，都会有一组与之相对应的锚点曝光参数。</p><p>但离开了太阳，我们就再也不能保证锚点是 1/125s 和 ISO100 了，太过奢侈，所以我们要稍微做一点点牺牲，我们用 1/60s 和 ISO400 来当锚点。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E5%258D%2581%25E4%25B8%2580%25E5%25B0%2581%25E4%25BF%25A1-%25E9%2598%25B3%25E5%2585%2589%25E4%25B9%258B%25E4%25B8%258B%25E6%25B2%25A1%25E4%25BB%2580%25E4%25B9%2588%25E6%2596%25B0%25E9%25B2%259C%25E4%25BA%258B%25E5%2584%25BF%25EF%25BC%2588%25E4%25B8%258B%25EF%25BC%2589/4.jpeg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E5%258D%2581%25E4%25B8%2580%25E5%25B0%2581%25E4%25BF%25A1-%25E9%2598%25B3%25E5%2585%2589%25E4%25B9%258B%25E4%25B8%258B%25E6%25B2%25A1%25E4%25BB%2580%25E4%25B9%2588%25E6%2596%25B0%25E9%25B2%259C%25E4%25BA%258B%25E5%2584%25BF%25EF%25BC%2588%25E4%25B8%258B%25EF%25BC%2589/4.jpeg" alt=""></a></p><ul><li>锚点曝光参数：1/60s F1.4 ISO400实际曝光参数：1/60s F2.8 ISO1600</li></ul><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E5%258D%2581%25E4%25B8%2580%25E5%25B0%2581%25E4%25BF%25A1-%25E9%2598%25B3%25E5%2585%2589%25E4%25B9%258B%25E4%25B8%258B%25E6%25B2%25A1%25E4%25BB%2580%25E4%25B9%2588%25E6%2596%25B0%25E9%25B2%259C%25E4%25BA%258B%25E5%2584%25BF%25EF%25BC%2588%25E4%25B8%258B%25EF%25BC%2589/5.jpeg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E5%258D%2581%25E4%25B8%2580%25E5%25B0%2581%25E4%25BF%25A1-%25E9%2598%25B3%25E5%2585%2589%25E4%25B9%258B%25E4%25B8%258B%25E6%25B2%25A1%25E4%25BB%2580%25E4%25B9%2588%25E6%2596%25B0%25E9%25B2%259C%25E4%25BA%258B%25E5%2584%25BF%25EF%25BC%2588%25E4%25B8%258B%25EF%25BC%2589/5.jpeg" alt=""></a></p><ul><li>锚点曝光参数：1/60s F2.8 ISO400实际曝光参数：1/125s F4 ISO1600</li></ul><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E5%258D%2581%25E4%25B8%2580%25E5%25B0%2581%25E4%25BF%25A1-%25E9%2598%25B3%25E5%2585%2589%25E4%25B9%258B%25E4%25B8%258B%25E6%25B2%25A1%25E4%25BB%2580%25E4%25B9%2588%25E6%2596%25B0%25E9%25B2%259C%25E4%25BA%258B%25E5%2584%25BF%25EF%25BC%2588%25E4%25B8%258B%25EF%25BC%2589/6.jpeg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E5%258D%2581%25E4%25B8%2580%25E5%25B0%2581%25E4%25BF%25A1-%25E9%2598%25B3%25E5%2585%2589%25E4%25B9%258B%25E4%25B8%258B%25E6%25B2%25A1%25E4%25BB%2580%25E4%25B9%2588%25E6%2596%25B0%25E9%25B2%259C%25E4%25BA%258B%25E5%2584%25BF%25EF%25BC%2588%25E4%25B8%258B%25EF%25BC%2589/6.jpeg" alt=""></a></p><ul><li>锚点曝光参数：1/60s F5.6 ISO400实际曝光参数：1/60s F5.6 ISO400</li></ul><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E5%258D%2581%25E4%25B8%2580%25E5%25B0%2581%25E4%25BF%25A1-%25E9%2598%25B3%25E5%2585%2589%25E4%25B9%258B%25E4%25B8%258B%25E6%25B2%25A1%25E4%25BB%2580%25E4%25B9%2588%25E6%2596%25B0%25E9%25B2%259C%25E4%25BA%258B%25E5%2584%25BF%25EF%25BC%2588%25E4%25B8%258B%25EF%25BC%2589/7.jpeg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E5%258D%2581%25E4%25B8%2580%25E5%25B0%2581%25E4%25BF%25A1-%25E9%2598%25B3%25E5%2585%2589%25E4%25B9%258B%25E4%25B8%258B%25E6%25B2%25A1%25E4%25BB%2580%25E4%25B9%2588%25E6%2596%25B0%25E9%25B2%259C%25E4%25BA%258B%25E5%2584%25BF%25EF%25BC%2588%25E4%25B8%258B%25EF%25BC%2589/7.jpeg" alt=""></a></p><ul><li>锚点曝光参数：1/60s F5.6 ISO400实际曝光参数：1/30s F8 ISO400</li></ul><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E5%258D%2581%25E4%25B8%2580%25E5%25B0%2581%25E4%25BF%25A1-%25E9%2598%25B3%25E5%2585%2589%25E4%25B9%258B%25E4%25B8%258B%25E6%25B2%25A1%25E4%25BB%2580%25E4%25B9%2588%25E6%2596%25B0%25E9%25B2%259C%25E4%25BA%258B%25E5%2584%25BF%25EF%25BC%2588%25E4%25B8%258B%25EF%25BC%2589/8.jpeg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E5%258D%2581%25E4%25B8%2580%25E5%25B0%2581%25E4%25BF%25A1-%25E9%2598%25B3%25E5%2585%2589%25E4%25B9%258B%25E4%25B8%258B%25E6%25B2%25A1%25E4%25BB%2580%25E4%25B9%2588%25E6%2596%25B0%25E9%25B2%259C%25E4%25BA%258B%25E5%2584%25BF%25EF%25BC%2588%25E4%25B8%258B%25EF%25BC%2589/8.jpeg" alt=""></a></p><ul><li>锚点曝光参数：1/60s F8 ISO400实际曝光参数：1/125s F5.6 ISO400</li></ul><p>我上一次说过，锚点曝光参数是不足以取得最正确的曝光的，会暗一档，但我还说过，前期暗一点点是好的……而现在的问题是，放出这些照片儿和这些照片儿的曝光参数有什么用？</p><p>还是我上次说的，要学会举一反三，所以，可不要把这五张照片儿当成五张照片儿来看，这是五种环境，分别是昏暗的 Jazz Bar、被路灯点亮的街道、布光均匀的地铁车厢、Nasdaq 交易所里最东边的一个小黑屋，交易所的西边是一长条的大落地窗，窗外就是时代广场，然后还有最后一张，山村木屋。</p><p>不要把这五张照片儿当成五张照片儿来看，这是五种环境，但也不要把这五种环境当成五种环境来看，因为这是五种甚至更多环境，知道了这五组锚点曝光参数以后，我以后再去有类似光线条件的地方，就可以直接知道曝光情况了。</p><p>比如 Jazz Bar，大部分带演出场地的酒吧基本都是那个光线条件；比如地铁车厢，虽然不同国家不同城市不同线路的地铁光线条件都不太一样，但大差不多，根据锚点，微调参数就可以做到随机应变；比如山村木屋，在达祖这个地方，基本所有屋子都这样，所以，当我需要在他们的木屋里进行拍摄的时候，我至少就不用太费心考虑曝光参数的问题了。</p><p>至于 Nasdaq 的小黑屋，那是光线条件比较好的一个空间里相对暗的地方，随着我往窗边移动，曝光情况会发生变化，根据经验，离窗最远最暗的地方和离窗最近最亮的地方，大概差着三到四档曝光。</p><p>总之就是，在我们的日常中，其实也就这么点生活场景了，加上家里、超市、餐馆、医院、办公区、大商场，你说你还能去哪儿吧……况且，其中很多地方，其实曝光情况是差不多的。</p><p>比如，我家客厅，目测比地铁车厢暗一点，地铁车厢的锚点曝光参数是 1/60sF5.6 ISO400，那我就可以知道我家客厅的锚点曝光参数大概是 1/60s F4 ISO400。</p><p>但我为了拍到下面这张照片儿，我需要更大的景深，而我的小 GR 又不能承受太高的 ISO，且我还要保证快门速度，因为毕竟三只动物里有两只都是完全不受控的，所以参数最终变成了1/60s F5.6 ISO800。</p><p>于是就有了这张照片儿：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E5%258D%2581%25E4%25B8%2580%25E5%25B0%2581%25E4%25BF%25A1-%25E9%2598%25B3%25E5%2585%2589%25E4%25B9%258B%25E4%25B8%258B%25E6%25B2%25A1%25E4%25BB%2580%25E4%25B9%2588%25E6%2596%25B0%25E9%25B2%259C%25E4%25BA%258B%25E5%2584%25BF%25EF%25BC%2588%25E4%25B8%258B%25EF%25BC%2589/9.jpeg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E5%258D%2581%25E4%25B8%2580%25E5%25B0%2581%25E4%25BF%25A1-%25E9%2598%25B3%25E5%2585%2589%25E4%25B9%258B%25E4%25B8%258B%25E6%25B2%25A1%25E4%25BB%2580%25E4%25B9%2588%25E6%2596%25B0%25E9%25B2%259C%25E4%25BA%258B%25E5%2584%25BF%25EF%25BC%2588%25E4%25B8%258B%25EF%25BC%2589/9.jpeg" alt=""></a></p><p>这次我多放了几张我自己拍的照片儿当例图，其实他们都不算是什么多好的照片儿，但技术上没什么问题，而且可以非常清楚地把我想讲的东西讲明白。</p><p>而你，现在需要做的，就是要练习怎么用肉眼测光，室外用阳光十六法则，室内分出几类大场景。相信我，如果你狠心弄，一个星期就可以搞定所有这些，很简单的。</p><p>了解基础曝光参数只是我们拍照片儿的第一步，希望前面的这几封信可以把你从相机的“自动曝光模式”和“自动测光模式”中解放出来，接下来，我们就要开始试着挣脱被“自动对焦模式”支配的恐惧了。再之后，我们大概就能彻底变成自由人了。</p><p>咱们之后有时间再继续聊。</p>',40)])])}const C=B(i,[["render",a]]);export{g as __pageData,C as default};
